import{_ as t,o as a,c as r,j as e,a as n,aa as o}from"./chunks/framework.BAs_AphD.js";const h=JSON.parse('{"title":"Signing with a Qualified Certificate","description":"","frontmatter":{"title":"Signing with a Qualified Certificate","wiki":"en:diary:qualifiedcertificate"},"headers":[],"relativePath":"en/diary/qualifiedcertificate.md","filePath":"en/diary/qualifiedcertificate.md","lastUpdated":1794388980000}'),c={name:"en/diary/qualifiedcertificate.md"};function s(d,i,l,u,f,p){return a(),r("div",null,[...i[0]||(i[0]=[e("h1",{id:"signing-with-a-qualified-certificate",tabindex:"-1"},[n("Signing with a Qualified Certificate "),e("a",{class:"header-anchor",href:"#signing-with-a-qualified-certificate","aria-label":'Permalink to "Signing with a Qualified Certificate"'},"​")],-1),e("figure",{class:"shot",style:{"--w":"600px"}},[e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/yraKCsEYoYc",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})])],-1),o('<p>Signing with a Qualified Certificate is the recommended signing method for diaries maintained under the Construction Act. A signing certificate can be obtained from a qualified trust service provider, such as PostSignum, a subsidiary of Česká pošta, or První certifikační autorita.</p><p><a href="https://www.postsignum.cz/" target="_blank" rel="noreferrer">PostSignum</a><a href="https://www.ica.cz/" target="_blank" rel="noreferrer">První certifikační autorita (I.CA)</a></p><p>The signing certificate can be stored on your computer, mobile device, token, or another secure storage device.</p><p>To sign with a qualified certificate from the web application, you need to install an auxiliary application on your computer.</p><p>To sign in the mobile application, you need to transfer the certificate to your mobile device and import it into the Buildary mobile application.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A signature created using a qualified certificate is, under eIDAS, either an <strong>Advanced Electronic Signature based on a Qualified Certificate</strong> or a <strong>Qualified Electronic Signature</strong>. In both cases, it constitutes a <strong>Recognized Electronic Signature</strong> under Czech law.</p></div>',6)])])}const m=t(c,[["render",s]]);export{h as __pageData,m as default};
